import{_ as o,r as s,o as p,c as i,e as a,a as l,s as c}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Widgets - October CMS - 3.x","titleTemplate":false,"description":"Self-contained blocks of functionality solving different tasks.","frontmatter":{"subtitle":"Self-contained blocks of functionality solving different tasks."},"headers":[{"level":2,"title":"Generic Widgets","slug":"generic-widgets","link":"#generic-widgets","children":[{"level":3,"title":"Class Definition","slug":"class-definition","link":"#class-definition","children":[]}]},{"level":2,"title":"Binding Widgets to Controllers","slug":"binding-widgets-to-controllers","link":"#binding-widgets-to-controllers","children":[]},{"level":2,"title":"Running Code Before AJAX Handlers","slug":"running-code-before-ajax-handlers","link":"#running-code-before-ajax-handlers","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/extend/system/widgets.md","filePath":"3.x/extend/system/widgets.md"}'),r={name:"3.x/extend/system/widgets.md"};function d(u,n,g,k,h,f){const e=s("pre-heading"),t=s("post-heading");return p(),i("div",null,[a(e),n[0]||(n[0]=l("h1",null,"Widgets",-1)),a(t),n[1]||(n[1]=c(`<p>Widgets are reusable controls that have a user interface and a backend controller (the widget class) that prepares the widget data and handles AJAX requests generated by the widget user interface.</p><h2 id="generic-widgets"><a href="#generic-widgets" class="header-anchor">#</a> Generic Widgets</h2><p>Widgets are the backend equivalent of <a href="./../../cms/themes/components.html">CMS Components</a>. They are similar because they are modular bundles of functionality, supply partials and are named using aliases. The key difference is that backend widgets use YAML markup for their configuration and bind themselves to backend controllers manually.</p><p>Widget classes reside inside the <strong>widgets</strong> directory of the plugin directory. The inner directory name matches the name of the widget class written in lowercase. Widgets can supply assets and partials. An example widget directory structure looks like this:</p><pre class="dir-container"><code><p>├── <code>widgets</code>
|   ├── form
|   |   ├── partials
|   |   |   └── _form.php  <em>← Partial File</em>
|   |   └── assets
|   |       ├── js
|   |       |   └── form.js  <em>← JavaScript File</em>
|   |       └── css
|   |           └── form.css  <em>← StyleSheet File</em>
|   └── Form.php  <em>← Widget Class</em></p>
</code></pre><h3 id="class-definition"><a href="#class-definition" class="header-anchor">#</a> Class Definition</h3><p>The generic widget classes must extend the <code>Backend\\Classes\\WidgetBase</code> class. As any other plugin class, generic widget controllers should belong to the <a href="./plugins.html">plugin namespace</a>. The following is an example of a widget class definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Backend<span class="token punctuation">\\</span>Widgets</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>WidgetBase</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Lists</span> <span class="token keyword">extends</span> <span class="token class-name">WidgetBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var string defaultAlias to identify this widget.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$defaultAlias</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The widget class must contain a <strong>render()</strong> method for producing the widget markup by rendering a widget partial. Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>To pass variables to partials you can either add them to the <code>$vars</code> property.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Alternatively you may pass the variables to the second parameter of the makePartial() method:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="binding-widgets-to-controllers"><a href="#binding-widgets-to-controllers" class="header-anchor">#</a> Binding Widgets to Controllers</h2><div class="custom-block aside"><p>Binding to a controller is also required to make <a href="./ajax.html">AJAX handlers available</a>.</p></div><p>A widget should be bound to a backend controller before you can start using it in a backend page or partial. Use the widget&#39;s <code>bindToController</code> method for binding it to a controller. The best place to initialize a widget is the controller&#39;s <code>beforeDisplay</code> method, which is called from the constructor.</p><p>For example, creating a new widget instance and binding it to the controller. Note the constructor takes the controller as the first argument.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeDisplay</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$myWidget</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyWidgetClass</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$myWidget</span><span class="token operator">-&gt;</span><span class="token property">alias</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;myWidget&#39;</span><span class="token punctuation">;</span>
    <span class="token variable">$myWidget</span><span class="token operator">-&gt;</span><span class="token function">bindToController</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>After binding the widget you can access it in the controller&#39;s view or partial by its alias using the <code>$this-&gt;widget</code> property.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">widget</span><span class="token operator">-&gt;</span><span class="token property">myWidget</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="running-code-before-ajax-handlers"><a href="#running-code-before-ajax-handlers" class="header-anchor">#</a> Running Code Before AJAX Handlers</h2><p>Sometimes you may want code to execute before an AJAX handler executes. Defining an <code>init</code> method in the widget allows code to run before every AJAX handler.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// From a widget class</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../forms/form-widgets.html">Form Widgets</a></li><li><a href="./../lists/filter-widgets.html">Filter Widgets</a></li><li><a href="./../backend/report-widgets.html">Report Widgets</a></li></ul></div>`,26))])}const y=o(r,[["render",d]]);export{w as __pageData,y as default};
